/// Bytes of `ROSETTE_XENIA_FATAL_POINT_ALLOW` kept.
const WINDOWS_FATAL_POINT_ALLOW_BYTES: usize = 512;

const GUEST_FILE_REQUEST_PREVIEW_BYTES: usize = 48;

