    pending_swap_fetch_valid: bool = false,
    pending_swap_fetch: [6]u32 = @splat(0),
    swap_frontbuffer: u32 = 0,
    swap_width: u32 = 0,
    swap_height: u32 = 0,
    /// Type-0 writes that land in the DC_LUT register range. These are the
