    decode_cache_clock: u64 = 0,
    decode_cache_miss_sites: [DECODE_CACHE_MISS_SITE_CAPACITY]DecodeCacheMissSite = [_]DecodeCacheMissSite{.{}} ** DECODE_CACHE_MISS_SITE_CAPACITY,
    decode_cache_miss_site_count: usize = 0,
